select
foodComment.*,
foods.dish_name as food_name,
foods.dish_img as banner_img,
foodUser.nick_name,
foodUser.head_img,
s.nick_name as nickNameTo,
s.head_img as headerImgTo
from food_comment foodComment
left join dish foods on foodComment.foods_id = foods.id
left join users foodUser on foodComment.user_id = foodUser.id
left join (select * from users) s on s.id = foodComment.to_user_id

    and foodComment.id = #{id}
    and foodComment.parent_id = #{parentId}
    and foodComment.comment_info = #{commentInfo}
    and foodComment.user_id = #{userId}
    and foodComment.foods_id = #{foodsId}
    and foodComment.create_time = #{createTime}
    and foods.dish_name like concat('%',#{foodName},'%')
    and foodUser.nick_name like concat('%',#{nickName},'%')
    and foodUser.head_img = #{headImg}

order by create_time desc

    limit #{current},#{pageSize}

select count(*) from food_comment foodComment
left join dish foods on foodComment.foods_id = foods.id
left join users foodUser on foodComment.user_id = foodUser.id
left join (select * from users) s on s.id = foodComment.to_user_id

    and foodComment.id = #{id}
    and foodComment.parent_id = #{parentId}
    and foodComment.comment_info = #{commentInfo}
    and foodComment.user_id = #{userId}
    and foodComment.foods_id = #{foodsId}
    and foodComment.create_time = #{createTime}
    and foods.food_name like concat('%',#{foodName},'%')
    and foodUser.nick_name like concat('%',#{nickName},'%')
    and foodUser.head_img = #{headImg}
